import { ethers } from "hardhat";

async function main() {
  console.log("🚀 Deploying EternaWill contract...");

  const EternaWill = await ethers.getContractFactory("EternaWill");
  const eternaWill = await EternaWill.deploy();
  await eternaWill.waitForDeployment();

  const address = await eternaWill.getAddress();
  console.log(`✅ EternaWill deployed to: ${address}`);
  console.log(`⛓️  Chain ID: ${(await ethers.provider.getNetwork()).chainId}`);

  // Verify on explorer (if not localhost)
  if (network.name !== "hardhat" && network.name !== "localhost") {
    console.log("⏳ Waiting for block confirmations...");
    await eternaWill.deploymentTransaction()?.wait(5);
    console.log(`🔍 Verify: npx hardhat verify --network ${network.name} ${address}`);
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

