1	import { createPublicClient, createWalletClient, custom, http, type Address } from "viem";
2	import { baseSepolia, sepolia } from "viem/chains";
3	import { config } from "./config";
4	import { ETERNA_WILL_ABI } from "./abi";
5	
6	const chain = config.chainId === 84532 ? baseSepolia : sepolia;
7	
8	export function getPublicClient() {
9	  return createPublicClient({
10	    chain,
11	    transport: http(config.rpcUrl),
12	  });
13	}
14	
15	export function getWalletClient() {
16	  return createWalletClient({
17	    chain,
18	    transport: custom((window as any).ethereum!),
19	  });
20	}
21	
22	export function getContract(address?: Address) {
23	  return {
24	    address: (address || config.contractAddress) as Address,
25	    abi: ETERNA_WILL_ABI,
26	  } as const;
27	}
28	
29	// ---- Will Creation ----
30	
31	export async function createWill(
32	  beneficiaries: Address[],
33	  percentages: bigint[],
34	  names: string[],
35	  delays: bigint[],
36	  guardians: Address[],
37	  guardianNames: string[],
38	  inactivityPeriod: bigint,
39	  guardianThreshold: bigint,
40	  minGuardians: bigint,
41	  encryptedDataHash: `0x${string}`
42	) {
43	  const walletClient = getWalletClient();
44	  const [account] = await walletClient.getAddresses();
45	
46	  const hash = await walletClient.writeContract({
47	    address: config.contractAddress as Address,
48	    abi: ETERNA_WILL_ABI,
49	    functionName: "createWill",
50	    args: [
51	      beneficiaries,
52	      percentages,
53	      names,
54	      delays,
55	      guardians,
56	      guardianNames,
57	      {
58	        inactivityPeriod,
59	        guardianThreshold,
60	        minGuardians,
61	        useOracle: false,
62	      },
63	      encryptedDataHash,
64	    ],
65	    account,
66	  });
67	
68	  const publicClient = getPublicClient();
69	  const receipt = await publicClient.waitForTransactionReceipt({ hash });
70	
71	  // Parse WillCreated event
72	  const log = receipt.logs[0];
73	  const willId = Number(log.topics[1]); // indexed willId
74	  return { hash, willId, receipt };
75	}
76	
77	// ---- Heartbeat ----
78	
79	export async function sendHeartbeat(willId: bigint) {
80	  const walletClient = getWalletClient();
81	  const [account] = await walletClient.getAddresses();
82	
