1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { useParams } from "next/navigation";
5	import { useAccount } from "wagmi";
6	import NavBar from "@/components/NavBar";
7	import {
8	  getWill,
9	  getWillStatus,
10	  getBeneficiaries,
11	  getGuardians,
12	  checkExecutable,
13	  isGuardian,
14	  sendHeartbeat,
15	  WILL_STATUS,
16	  formatTimeLeft,
17	} from "@/lib/eterna";
18	
19	export default function WillDetailPage() {
20	  const { id } = useParams<{ id: string }>();
21	  const { address } = useAccount();
22	  const willId = BigInt(id);
23	
24	  const [will, setWill] = useState<any>(null);
25	  const [status, setStatus] = useState<any>(null);
26	  const [beneficiaries, setBeneficiaries] = useState<any[]>([]);
27	  const [guardians, setGuardians] = useState<any[]>([]);
28	  const [executable, setExecutable] = useState<boolean | null>(null);
29	  const [confidence, setConfidence] = useState(0);
30	  const [isUserGuardian, setIsUserGuardian] = useState(false);
31	  const [loading, setLoading] = useState(true);
32	  const [heartbeatLoading, setHeartbeatLoading] = useState(false);
33	  const [heartbeatMsg, setHeartbeatMsg] = useState("");
34	
35	  useEffect(() => {
36	    loadData();
37	  }, [id, address]);
38	
39	  async function loadData() {
40	    setLoading(true);
41	    try {
42	      const [w, s, b, g, e] = await Promise.all([
43	        getWill(willId),
44	        getWillStatus(willId),
45	        getBeneficiaries(willId),
46	        getGuardians(willId),
47	        checkExecutable(willId),
48	      ]);
49	      setWill(w);
50	      setStatus(s);
51	      setBeneficiaries([...b]);
52	      setGuardians([...g]);
53	      setExecutable(e[0]);
54	      setConfidence(Number(e[1]));
55	
56	      if (address) {
57	        const isG = await isGuardian(willId, address);
58	        setIsUserGuardian(isG);
59	      }
60	    } catch (err) {
61	      console.error("Error loading will:", err);
62	    } finally {
63	      setLoading(false);
64	    }
65	  }
66	
67	  const handleHeartbeat = async () => {
68	    setHeartbeatLoading(true);
69	    setHeartbeatMsg("");
70	    try {
71	      await sendHeartbeat(willId);
72	      setHeartbeatMsg("Heartbeat registered successfully!");
73	      loadData();
74	    } catch (err: any) {
75	      setHeartbeatMsg(err?.shortMessage || "Failed to send heartbeat");
76	    } finally {
77	      setHeartbeatLoading(false);
78	    }
79	  };
80	
81	  if (loading) {
82	    return (
83	      <div className="flex-1 flex flex-col">
84	        <NavBar />
85	        <div className="flex-1 flex items-center justify-center">
86	          <div className="w-8 h-8 border-2 border-purple-500/30 border-t-purple-500 rounded-full animate-spin" />
87	        </div>
88	      </div>
89	    );
90	  }
91	
92	  if (!will) {
93	    return (
94	      <div className="flex-1 flex flex-col">
95	        <NavBar />
96	        <div className="flex-1 flex items-center justify-center">
97	          <div className="card text-center">
98	            <h2 className="text-xl font-bold mb-2">Will Not Found</h2>
99	            <p className="text-gray-400">This will does not exist or could not be loaded.</p>
100	          </div>
101	        </div>
102	      </div>
103	    );
104	  }
105	
106	  const willStatus = Number(will.status);
107	  const isOwner = address && will.owner.toLowerCase() === address.toLowerCase();
108	  const inactivityScore = status ? Number(status[2]) : 0;
109	  const guardianScore = status ? Number(status[3]) : 0;
110	  const lastHeartbeat = will.lastHeartbeat ? Number(will.lastHeartbeat) : 0;
111	
112	  return (
113	    <div className="flex-1 flex flex-col">
114	      <NavBar />
115	
116	      <main className="flex-1 max-w-4xl mx-auto px-4 py-8 w-full">
117	        {/* Header */}
118	        <div className="flex items-start justify-between mb-8">
119	          <div>
120	            <h1 className="text-3xl font-bold">Will #{id}</h1>
121	            <p className="text-gray-400 text-sm mt-1">
122	              Created {new Date(Number(will.createdAt) * 1000).toLocaleDateString()}
123	            </p>
124	          </div>
125	          <span
126	            className={`px-3 py-1.5 rounded-full text-sm font-medium ${
127	              willStatus === 0
128	                ? "bg-emerald-900/30 text-emerald-400 border border-emerald-500/30"
129	                : willStatus === 1
130	                ? "bg-blue-900/30 text-blue-400 border border-blue-500/30"
131	                : "bg-gray-800 text-gray-400 border border-gray-700"
132	            }`}
133	          >
134	            {WILL_STATUS[willStatus]}
135	          </span>
136	        </div>
137	
138	        {/* Status Cards */}
139	        <div className="grid md:grid-cols-4 gap-4 mb-8">
140	          <div className="card">
141	            <p className="text-xs text-gray-500 uppercase tracking-wide mb-1">Overall Confidence</p>
142	            <p className="text-2xl font-bold gradient-text">
143	              {Math.max(inactivityScore, guardianScore) / 100}%
144	            </p>
145	          </div>
146	          <div className="card">
147	            <p className="text-xs text-gray-500 uppercase tracking-wide mb-1">Inactivity Score</p>
148	            <div className="flex items-end gap-2">
149	              <p className="text-2xl font-bold">{inactivityScore / 100}%</p>
150	              <div className="flex-1 h-2 bg-gray-800 rounded-full overflow-hidden">
151	                <div
152	                  className="h-full bg-purple-500 rounded-full transition-all"
153	                  style={{ width: `${Math.min(100, inactivityScore / 100)}%` }}
154	                />
155	              </div>
156	            </div>
157	          </div>
158	          <div className="card">
159	            <p className="text-xs text-gray-500 uppercase tracking-wide mb-1">Guardian Score</p>
160	            <div className="flex items-end gap-2">
161	              <p className="text-2xl font-bold">{guardianScore / 100}%</p>
162	              <div className="flex-1 h-2 bg-gray-800 rounded-full overflow-hidden">
163	                <div
164	                  className="h-full bg-blue-500 rounded-full transition-all"
165	                  style={{ width: `${Math.min(100, guardianScore / 100)}%` }}
166	                />
167	              </div>
168	            </div>
169	          </div>
170	          <div className="card">
171	            <p className="text-xs text-gray-500 uppercase tracking-wide mb-1">Last Heartbeat</p>
172	            <p className="text-2xl font-bold">
173	              {lastHeartbeat > 0
174	                ? new Date(lastHeartbeat * 1000).toLocaleDateString()
175	                : "—"}
176	            </p>
177	          </div>
178	        </div>
179	
180	        {/* Owner Actions */}
181	        {isOwner && willStatus === 0 && (
182	          <div className="card card-glow mb-8">
183	            <div className="flex items-center justify-between">
184	              <div>
185	                <h3 className="font-semibold">Owner Actions</h3>
186	                <p className="text-sm text-gray-400">Send a heartbeat to prove you are active</p>
187	              </div>
188	              <button
189	                onClick={handleHeartbeat}
190	                disabled={heartbeatLoading}
191	                className="btn-primary"
192	              >
193	                {heartbeatLoading ? "Sending..." : "💓 Send Heartbeat"}
194	              </button>
195	            </div>
196	            {heartbeatMsg && (
197	              <p className={`text-sm mt-2 ${heartbeatMsg.includes("success") ? "text-emerald-400" : "text-red-400"}`}>
198	                {heartbeatMsg}
199	              </p>
200	            )}
201	          </div>
202	        )}
203	
204	        {/* Guardian Actions */}
205	        {isUserGuardian && willStatus === 0 && (
206	          <GuardianVotePanel willId={willId} guardians={guardians} address={address!} onVote={loadData} />
207	        )}
208	
209	        {/* Beneficiaries */}
210	        <div className="card mb-6">
211	          <h3 className="text-lg font-semibold mb-4">Beneficiaries</h3>
212	          {beneficiaries.length === 0 ? (
213	            <p className="text-gray-500 text-sm">No beneficiaries configured</p>
214	          ) : (
215	            <div className="space-y-3">
216	              {beneficiaries.map((b: any, i: number) => (
217	                <div key={i} className="flex items-center justify-between py-2 border-b border-white/5 last:border-0">
218	                  <div>
219	                    <p className="font-medium">{b.name}</p>
220	                    <p className="text-xs text-gray-500 font-mono">{b.wallet}</p>
221	                  </div>
222	                  <div className="text-right">
223	                    <p className="text-lg font-bold gradient-text">{Number(b.percentage) / 100}%</p>
224	                    <p className="text-xs text-gray-500">
225	                      {b.claimed ? "✅ Claimed" : Number(b.delaySeconds) > 0 ? `Delayed ${Number(b.delaySeconds) / 86400}d` : "Pending"}
226	                    </p>
227	                  </div>
228	                </div>
229	              ))}
230	            </div>
231	          )}
232	        </div>
233	
234	        {/* Guardians */}
235	        <div className="card">
236	          <h3 className="text-lg font-semibold mb-4">Guardians</h3>
237	          {guardians.length === 0 ? (
238	            <p className="text-gray-500 text-sm">No guardians configured</p>
239	          ) : (
240	            <div className="space-y-3">
241	              {guardians.map((g: any, i: number) => (
242	                <div key={i} className="flex items-center justify-between py-2 border-b border-white/5 last:border-0">
243	                  <div>
244	                    <p className="font-medium">{g.name}</p>
245	                    <p className="text-xs text-gray-500 font-mono">{g.wallet}</p>
246	                  </div>
247	                  <div className="text-right">
248	                    {g.hasVoted ? (
249	                      <span className={g.vote ? "text-emerald-400" : "text-gray-500"}>
250	                        {g.vote ? "✅ Voted: Deceased" : "Voted: Alive"}
251	                      </span>
252	                    ) : (
253	                      <span className="text-gray-500">Not voted</span>
254	                    )}
255	                  </div>
256	                </div>
257	              ))}
258	            </div>
259	          )}
260	        </div>
261	      </main>
262	    </div>
263	  );
264	}
265	
266	function GuardianVotePanel({
267	  willId,
268	  guardians,
269	  address,
270	  onVote,
271	}: {
272	  willId: bigint;
273	  guardians: any[];
274	  address: `0x${string}`;
275	  onVote: () => void;
276	}) {
277	  const [voting, setVoting] = useState(false);
278	  const [error, setError] = useState("");
279	
280	  const myVote = guardians.find(
281	    (g: any) => g.wallet.toLowerCase() === address.toLowerCase()
282	  );
283	
284	  if (myVote?.hasVoted) {
285	    return (
286	      <div className="card border-emerald-500/20 mb-8">
287	        <p className="text-sm text-emerald-400">✅ You have voted as a guardian</p>
288	      </div>
289	    );
290	  }
291	
292	  const handleVote = async (deceased: boolean) => {
293	    setVoting(true);
294	    setError("");
295	    try {
296	      const { voteAsGuardian } = await import("@/lib/eterna");
297	      await voteAsGuardian(willId, deceased);
298	      onVote();
299	    } catch (err: any) {
300	      setError(err?.shortMessage || "Vote failed");
301	    } finally {
302	      setVoting(false);
303	    }
304	  };
305	
306	  return (
307	    <div className="card card-glow border-yellow-500/20 mb-8">
308	      <h3 className="font-semibold mb-2">Guardian Vote Required</h3>
309	      <p className="text-sm text-gray-400 mb-4">
310	        As a guardian for this will, please confirm whether you believe the owner is deceased.
311	      </p>
312	      <div className="flex gap-3">
